const b = $input.first().json.body || {};
const conv = b.conversation || {};
const sender = b.sender || {};

return [{
  json: {
    conversationId: conv.id,
    inboxId: conv.inbox_id,
    accountId: conv.account_id || 1,
    contactId: sender.id,
    contactName: sender.name || "Visitor",
    contactEmail: sender.email || "",
    contactPhone: sender.phone_number || "",
    message: (b.content || "").trim(),
    messageId: b.id
  }
}];
